/**
 * A rã-de-vidro — invisível na folha, e viva.
 *
 * Ela some recolhendo quase todas as hemácias para o fígado: sem o vermelho
 * circulando, o corpo vira quase um vidro. O truque é que sangue tão concentrado
 * COAGULA — e ela tem, na medida, uma ação anticoagulante que o impede enquanto
 * está guardado, sem perder a coagulação normal de um ferimento.
 *
 * São dois sliders que se contradizem, e a leitura sozinha não deixa isso óbvio.
 * A cena põe as três consequências lado a lado: **a rã sumindo na folha**, **o
 * fígado enchendo** e **o vaso** — que ou está limpo, ou entupido por um coágulo,
 * ou vazando porque o anticoagulante passou do ponto.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  disco,
  type EstadoDaViz,
  etiqueta,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const FOLHA = '#4e8f43';
const FOLHA_ESCURA = '#3a6f32';
const NERVURA = '#6fae5e';
const RA = '#b9d98f';
const SANGUE = '#b4342f';

const raVidro: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /** A folha ao fundo, com a nervura central — é o que se vê ATRAVÉS da rã. */
  function folha(
    ctx: CanvasRenderingContext2D,
    L: number,
    A: number,
    y0: number,
    y1: number,
  ): void {
    const grad = ctx.createLinearGradient(0, y0, 0, y1);
    grad.addColorStop(0, FOLHA);
    grad.addColorStop(1, FOLHA_ESCURA);
    ctx.fillStyle = grad;
    ctx.fillRect(0, y0, L, y1 - y0);

    ctx.strokeStyle = NERVURA;
    ctx.lineWidth = Math.max(2, A * 0.008);
    ctx.beginPath();
    ctx.moveTo(0, y1 - (y1 - y0) * 0.22);
    ctx.lineTo(L, y0 + (y1 - y0) * 0.28);
    ctx.stroke();

    ctx.lineWidth = Math.max(1, A * 0.004);
    for (let i = 1; i < 7; i++) {
      const u = i / 7;
      const bx = u * L;
      const by = y1 - (y1 - y0) * 0.22 + u * ((y1 - y0) * -0.5);
      ctx.beginPath();
      ctx.moveTo(bx, by);
      ctx.lineTo(bx + L * 0.1, by - (y1 - y0) * 0.3);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(bx, by);
      ctx.lineTo(bx - L * 0.06, by + (y1 - y0) * 0.28);
      ctx.stroke();
    }
  }

  /** A rã de barriga para cima, vista de baixo — como quem a vê na folha. */
  function corpo(
    ctx: CanvasRenderingContext2D,
    cx: number,
    cy: number,
    raio: number,
    opacidade: number,
    corSangue: number,
  ): void {
    const cor = paleta();

    ctx.save();
    ctx.globalAlpha = opacidade;

    // As patas, antes do tronco, para saírem por baixo.
    ctx.fillStyle = RA;
    ctx.strokeStyle = 'rgb(40 60 30 / 55%)';
    ctx.lineWidth = 1.2;
    for (const [dx, dy, ang] of [
      [-0.8, -0.5, -0.7],
      [0.8, -0.5, 0.7],
      [-0.85, 0.55, -2.5],
      [0.85, 0.55, 2.5],
    ] as const) {
      ctx.save();
      ctx.translate(cx + raio * dx, cy + raio * dy);
      ctx.rotate(ang);
      ctx.beginPath();
      ctx.ellipse(0, 0, raio * 0.5, raio * 0.2, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
      ctx.restore();
    }

    // O tronco.
    ctx.beginPath();
    ctx.ellipse(cx, cy, raio * 0.75, raio * 0.62, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    // A cabeça, e os olhos por cima dela.
    ctx.beginPath();
    ctx.ellipse(cx, cy - raio * 0.62, raio * 0.48, raio * 0.38, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    for (const lado of [-1, 1]) {
      disco(ctx, cx + lado * raio * 0.28, cy - raio * 0.82, raio * 0.16, '#f2f6ea');
      disco(ctx, cx + lado * raio * 0.28, cy - raio * 0.82, raio * 0.08, cor.texto);
    }

    // O sangue que AINDA circula: some conforme vai para o fígado.
    ctx.globalAlpha = opacidade * corSangue;
    ctx.strokeStyle = SANGUE;
    ctx.lineWidth = Math.max(1, raio * 0.05);
    for (const lado of [-1, 1]) {
      ctx.beginPath();
      ctx.moveTo(cx + lado * raio * 0.05, cy - raio * 0.3);
      ctx.bezierCurveTo(
        cx + lado * raio * 0.5,
        cy - raio * 0.1,
        cx + lado * raio * 0.35,
        cy + raio * 0.35,
        cx + lado * raio * 0.15,
        cy + raio * 0.55,
      );
      ctx.stroke();
    }

    ctx.restore();
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);

    const armazenado = limitar(numeroDe(info, 'arm', 0), 0, 100);
    const anticoag = limitar(numeroDe(info, 'anti', 0), 0, 100);
    const transparencia = limitar(numeroDe(info, 'transp', armazenado), 0, 100);
    const alvo = numeroDe(info, 'alvo', 89);
    const coagulo = info.coagulo === true;
    const sangramento = info.sangramento === true;
    const ok = info.ok === true;

    titulo(ctx, L, A, 'Some sem coagular — as duas coisas ao mesmo tempo');

    // ── A folha e a rã ────────────────────────────────────────────────────
    const yFolha0 = A * 0.18;
    const yFolha1 = A * 0.66;
    ctx.save();
    ctx.beginPath();
    ctx.roundRect(L * 0.04, yFolha0, L * 0.55, yFolha1 - yFolha0, 8);
    ctx.clip();
    folha(ctx, L, A, yFolha0, yFolha1);

    // Transparente demais é literalmente apagada: é o ponto do módulo.
    const opacidade = limitar(1 - transparencia / 100, 0.06, 1);
    corpo(
      ctx,
      L * 0.315,
      (yFolha0 + yFolha1) / 2,
      Math.min(L * 0.12, (yFolha1 - yFolha0) * 0.3),
      opacidade,
      limitar(1 - armazenado / 100, 0, 1),
    );
    ctx.restore();

    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.roundRect(L * 0.04, yFolha0, L * 0.55, yFolha1 - yFolha0, 8);
    ctx.stroke();

    const miudo = limitar(A * 0.03, 8, 11);
    etiqueta(
      ctx,
      `transparência ${Math.round(transparencia)}%  (alvo ${Math.round(alvo)}%)`,
      L * 0.315,
      yFolha1 - miudo * 1.6,
      miudo,
      transparencia >= alvo ? cor.verde : cor.texto,
      700,
    );

    // ── O fígado, à direita, enchendo ─────────────────────────────────────
    const fx = L * 0.79;
    const fy = A * 0.3;
    const fRaio = Math.min(L * 0.13, A * 0.16);

    ctx.save();
    ctx.beginPath();
    ctx.ellipse(fx, fy, fRaio, fRaio * 0.78, 0, 0, Math.PI * 2);
    ctx.clip();
    ctx.fillStyle = '#f0e3dd';
    ctx.fillRect(fx - fRaio, fy - fRaio, fRaio * 2, fRaio * 2);
    // O nível sobe com o que foi recolhido.
    const nivel = fy + fRaio * 0.78 - fRaio * 1.56 * (armazenado / 100);
    ctx.fillStyle = coagulo ? '#6d1f1b' : SANGUE;
    ctx.fillRect(fx - fRaio, nivel, fRaio * 2, fRaio * 2);
    // Coagulado, o conteúdo deixa de ondular e ganha grumos.
    if (coagulo) {
      ctx.fillStyle = '#4d1512';
      for (let i = 0; i < 7; i++) {
        const u = (i + 0.5) / 7;
        disco(
          ctx,
          fx - fRaio + u * fRaio * 2,
          nivel + fRaio * (0.3 + (i % 3) * 0.22),
          fRaio * 0.13,
          ctx.fillStyle,
        );
      }
    }
    ctx.restore();

    ctx.strokeStyle = cor.texto;
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.ellipse(fx, fy, fRaio, fRaio * 0.78, 0, 0, Math.PI * 2);
    ctx.stroke();
    texto(ctx, 'fígado', fx, fy + fRaio * 0.78 + miudo * 1.3, miudo, {
      cor: cor.fraco,
      peso: 700,
    });

    // ── O vaso: o teste do ferimento ──────────────────────────────────────
    const vx0 = L * 0.66;
    const vx1 = L * 0.94;
    const vy = A * 0.58;
    const espessura = Math.max(5, A * 0.026);

    retangulo(
      ctx,
      vx0,
      vy - espessura / 2,
      vx1 - vx0,
      espessura,
      espessura / 2,
      coagulo ? '#8f2b26' : SANGUE,
      cor.texto,
      1.2,
    );

    if (coagulo) {
      // O tampão que não deveria estar ali.
      disco(ctx, (vx0 + vx1) / 2, vy, espessura * 0.9, '#4d1512');
      etiqueta(ctx, 'coágulo', (vx0 + vx1) / 2, vy - espessura * 2, miudo, cor.erro, 800);
    } else if (sangramento) {
      // A gota que não estanca, caindo em laço.
      const queda = ((t * 0.8) % 1) * A * 0.12;
      ctx.fillStyle = SANGUE;
      ctx.beginPath();
      ctx.ellipse(
        (vx0 + vx1) / 2,
        vy + espessura / 2 + queda,
        espessura * 0.32,
        espessura * 0.45,
        0,
        0,
        Math.PI * 2,
      );
      ctx.fill();
      etiqueta(ctx, 'não estanca', (vx0 + vx1) / 2, vy - espessura * 2, miudo, cor.erro, 800);
    } else {
      etiqueta(ctx, 'vaso livre', (vx0 + vx1) / 2, vy - espessura * 2, miudo, cor.verde, 700);
    }

    // ── Os dois níveis, lado a lado ───────────────────────────────────────
    const yBarra = A * 0.76;
    const alturaBarra = limitar(A * 0.032, 6, 10);
    const largura = L * 0.38;

    const medidor = (x: number, rotulo: string, valor: number, tinta: string): void => {
      retangulo(ctx, x, yBarra, largura, alturaBarra, alturaBarra / 2, cor.palha, cor.trilho, 1);
      retangulo(ctx, x, yBarra, (largura * valor) / 100, alturaBarra, alturaBarra / 2, tinta);
      texto(ctx, `${rotulo} ${Math.round(valor)}%`, x + largura / 2, yBarra - miudo, miudo * 0.95, {
        cor: cor.fraco,
        peso: 700,
      });
    };

    medidor(L * 0.06, 'guardado', armazenado, SANGUE);
    medidor(L * 0.56, 'anticoagulante', anticoag, sangramento ? cor.erro : cor.azul);

    rodape(
      ctx,
      L,
      A,
      ok,
      'Invisível na folha, e sem um coágulo sequer ✔',
      coagulo
        ? 'O sangue concentrado coagulou: aumente a ação anticoagulante.'
        : sangramento
          ? 'Anticoagulante demais: um arranhão não pararia de sangrar.'
          : 'Ainda dá para vê-la na folha — esconda mais hemácias no fígado.',
      cor.erro,
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default raVidro;
